import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute, RouterModule } from '@angular/router';

import { Job } from 'src/app/landing/models/job';
import { JobService } from 'src/app/service/job/job.service';
import { SharedModule } from 'src/app/shared/shared.module';

@Component({
  selector: 'app-all-jobs',
  templateUrl: './all-jobs.component.html',
  styleUrls: ['./all-jobs.component.css'],
  standalone: true,
  imports: [CommonModule, FormsModule, RouterModule, SharedModule]
})
export class AllJobsComponent implements OnInit {

  allJobs: Job[] = [];

  searchTerm = '';
  selectedLocation = 'Any location';
  selectedExperience = 'Any level';
  selectedSkills: Set<string> = new Set();

  constructor(private jobService: JobService, private route: ActivatedRoute) {}

  ngOnInit(): void {
    // Prefill the keyword search when arriving from the landing-page search box.
    const q = this.route.snapshot.queryParamMap.get('q');
    if (q) {
      this.searchTerm = q;
    }
    this.getAllJobs();
  }

  getAllJobs(): void {
    this.jobService.getAllJobs().subscribe(res => {
      this.allJobs = res || [];
    });
  }

  toggleSkill(skill: string): void {
    if (this.selectedSkills.has(skill)) {
      this.selectedSkills.delete(skill);
    } else {
      this.selectedSkills.add(skill);
    }
  }

  clearFilters(): void {
    this.searchTerm = '';
    this.selectedLocation = 'Any location';
    this.selectedExperience = 'Any level';
    this.selectedSkills.clear();
  }

  get locations(): string[] {
    const set = new Set(this.allJobs.map(j => j.location).filter(Boolean));
    return ['Any location', ...Array.from(set).sort()];
  }

  get experienceLevels(): string[] {
    const set = new Set(this.allJobs.map(j => j.experience).filter(Boolean));
    return ['Any level', ...Array.from(set).sort()];
  }

  get availableSkills(): string[] {
    const set = new Set<string>();
    this.allJobs.forEach(j => (j.skills || []).forEach(s => set.add(s)));
    return Array.from(set).sort();
  }

  get filteredJobs(): Job[] {
    const term = this.searchTerm.trim().toLowerCase();
    return this.allJobs.filter(job => {
      const matchesTerm = !term
        || (job.jobTitle || '').toLowerCase().includes(term)
        || (job.companyName || '').toLowerCase().includes(term)
        || (job.skills || []).some(s => s.toLowerCase().includes(term));

      const matchesLocation = this.selectedLocation === 'Any location' || job.location === this.selectedLocation;
      const matchesExperience = this.selectedExperience === 'Any level' || job.experience === this.selectedExperience;
      const matchesSkills = this.selectedSkills.size === 0
        || (job.skills || []).some(s => this.selectedSkills.has(s));

      return matchesTerm && matchesLocation && matchesExperience && matchesSkills;
    });
  }
}
<div class="page">
<app-header variant="guest"></app-header>

<section class="section-pad">
  <div class="wrap">
    <div class="section-head">
      <h2>{{filteredJobs.length}} open role{{filteredJobs.length === 1 ? '' : 's'}}</h2>
      <input type="text" [(ngModel)]="searchTerm" placeholder="Search by keyword" style="padding:10px 14px;border:1px solid var(--line);border-radius:8px;width:280px;">
    </div>
    <div class="browse-grid">
      <div class="filters">
        <h4>Filters</h4>
        <div class="filter-group"><span class="lbl">Location</span>
          <select [(ngModel)]="selectedLocation">
            <option *ngFor="let loc of locations" [value]="loc">{{ loc }}</option>
          </select>
        </div>
        <div class="filter-group"><span class="lbl">Experience</span>
          <select [(ngModel)]="selectedExperience">
            <option *ngFor="let exp of experienceLevels" [value]="exp">{{ exp }}</option>
          </select>
        </div>
        <div class="filter-group" *ngIf="availableSkills.length">
          <span class="lbl">Skills</span>
          <span *ngFor="let skill of availableSkills"
                class="chip-choice"
                [class.selected]="selectedSkills.has(skill)"
                (click)="toggleSkill(skill)"
                style="cursor:pointer;">{{ skill }}</span>
        </div>
        <button class="btn btn-primary btn-block" (click)="clearFilters()">Clear filters</button>
      </div>
      <div class="table-wrap">
        <table>
          <thead><tr><th>Role</th><th>Company</th><th>Location</th><th>Salary</th><th>Status</th><th></th></tr></thead>
          <tbody>
            <tr *ngFor="let job of filteredJobs">
              <td>{{job.jobTitle}}</td>
              <td>{{job.companyName}}</td>
              <td>{{job.location}}</td>
              <td>&#8377;{{job.salary}}</td>
              <td><span class="chip" [ngClass]="job.active ? 'chip-open' : 'chip-closed'">{{ job.active ? 'Open' : 'Closed' }}</span></td>
              <td class="actions"><a [routerLink]="['/job/view-job', job.jobId]">View</a></td>
            </tr>
            <tr *ngIf="filteredJobs.length === 0">
              <td colspan="6" style="text-align:center;color:var(--muted);padding:24px;">No jobs match your filters.</td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  </div>
</section>

<app-footer></app-footer>
</div>
